            raise FloatingPointError(
                "non-finite value encountered during multiclass-log-loss "
                "computation"
            )
        loss_terms.append(term)

    try:
        total_loss = math.fsum(loss_terms)
        loss = total_loss / total_weight
    except (OverflowError, ValueError) as exc:
        raise FloatingPointError(
            "non-finite value encountered during multiclass-log-loss "
            "computation"
        ) from exc
